1	<!doctype html>
2	<!--
3	  KEYNOTE PRO  -  one-file HTML presentation template.
4	  1. Copy this file.  2. Set data-theme / data-fonts on <html> and the title below.
5	  3. Replace the slides between SLIDES:START and SLIDES:END.  4. Open in a browser. That is all.
6	  Keys: arrows/space next-back, O outline, G overview (Esc only closes), P presenter view, M marker (H highlighter, Ctrl/Cmd+Z undo), L laser, S theme+fonts (hover previews), F fullscreen, B/W black/white, 12 Enter jump.
7	  Docs: README.md.  Engine: the <style id="kp-engine"> and <script> blocks (no dependencies; fonts load from Google on demand).
8	-->
9	<html lang="en" data-theme="keynote-white" data-fonts="">
10	<head>
11	<meta charset="utf-8">
12	<meta name="viewport" content="width=device-width, initial-scale=1">
13	<title>present-in-html template</title>
14	<style id="kp-themes">
15	/* =====================================================================
16	   THEME TOKEN CONTRACT
17	   A theme is ONE block: a marker comment "THEME:name | Label | swatch | fonts-url" (written as a CSS comment),
18	   then html[data-theme="name"]{ ... }, then a closing comment "/THEME". See the real blocks below.
19	   Layouts and components read ONLY these tokens (no colour, font or weight is hard-coded in layout CSS).
20	   Themes may add small signature rules (decorations) inside their own block, scoped by [data-theme="name"].
21	   The settings panel (S) lists whatever THEME / FONTS blocks exist in this <style>. Scripts can add or remove blocks.
22	
23	   COLOUR (required)
24	     --bg --bg2          slide background, quiet panel/surface
25	     --ink --ink2        body text, secondary text   (>= 4.5:1 on --bg and --bg2)
26	     --rule              hairline colour             --rule-strong   hard rule / table head / outline colour
27	     --brand             the one accent (fills, bars, dots)      --brand-text  accent used as TEXT (>= 4.5:1 on --bg)
28	     --on-brand          text drawn on a --brand fill
29	   HERO SLIDES (title, section, closing, full-bleed, data-tone="hero"; required)
30	     --hero-bg --hero-ink --hero-ink2 --hero-rule --hero-brand
31	   FULL-BLEED PLACEHOLDER (required)     --bleed-bg  --bleed-ink    (no-image full-bleed slides; ink >= 4.5:1 on bg)
32	   TYPE (required)
33	     --f-display --f-body --f-mono       font stacks (end with a generic family)
34	     --w-display --ls-display            display weight, display letter-spacing
35	     --em-style                          <em> in headings: italic | normal (it takes the slide's --brand-text)
36	     --em-fill (optional)                a fixed gradient for headline <em> (e.g. keynote-black); omit to use --brand-text
37	   SHAPE (required)
38	     --radius        panels, process boxes, chips, code panel      --chart-radius  bar corner radius (px number)
39	     --rule-w        weight of structural rules (1px | 2px)
40	   CHART + DIAGRAM PALETTE (optional, defaults below)
41	     --s1 --s2 --s3  series colours      --muted-bar  de-emphasised bars      --hot  highlight colour (diagrams, chips)
42	     --rec-mix       tint of the recommended comparison column (13% light themes, about 24% on dark ones)
43	   ARABIC (optional)  --f-ar-d  display face for Arabic headings (Naskh for serif themes); default IBM Plex Sans Arabic
44	   TYPE SCALE (engine tokens, do not override per theme)  --t-display --t-h1 --t-h2 --t-h3 --t-body --t-small (28px floor)
45	   CODE (required)   --code-bg --code-ink --c-kw --c-str --c-num --c-com --c-fn   (each >= 4.5:1 on --code-bg)
46	   IMAGE OVERLAY (optional)    --scrim (gradient or colour under full-bleed titles)   --on-image (text on photos)
47	   CHROME           --letterbox   colour around the 16:9 stage
48	   ===================================================================== */
49	/* DEFAULTS: every optional token has a fallback here */
50	html{--rule-w:1px;--s1:var(--brand);--s2:var(--ink);--s3:color-mix(in srgb,var(--ink) 38%,var(--bg));--muted-bar:color-mix(in srgb,var(--ink) 32%,var(--bg));--hot:var(--brand);--rec-mix:13%;
51	  --scrim:linear-gradient(to top,rgba(0,0,0,.72) 0,rgba(0,0,0,.35) 45%,rgba(0,0,0,0) 75%);--on-image:#fff;
52	  /* TYPE SCALE (px on the 1920 stage). --display-scale (set per font pairing) evens out faces with a small x-height. 28px is the floor for anything the audience reads. */
53	  --t-display:calc(164px*var(--display-scale,1));--t-h1:calc(132px*var(--display-scale,1));--t-h2:calc(84px*var(--display-scale,1));--t-h3:48px;--t-body:36px;--t-small:28px}
54	
55	/* =====================================================================
56	   THEMES
57	   ===================================================================== */
58	/* THEME:keynote-white | Keynote White | #0066cc | https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap */
59	html[data-theme="keynote-white"]{
60	  --bleed-bg:#0066cc; --bleed-ink:#ffffff;
61	  --bg:#ffffff; --bg2:#f5f5f7; --ink:#1d1d1f; --ink2:#5f5f64;
62	  --rule:#d2d2d7; --rule-strong:#1d1d1f; --brand:#0066cc; --brand-text:#0066cc; --on-brand:#ffffff;
63	  --hero-bg:#ffffff; --hero-ink:#1d1d1f; --hero-ink2:#5f5f64; --hero-rule:#d2d2d7; --hero-brand:#0066cc;
64	  --f-display:"Inter","SF Pro Display",-apple-system,"Helvetica Neue",Arial,sans-serif;
65	  --f-body:"Inter","SF Pro Text",-apple-system,"Helvetica Neue",Arial,sans-serif;
66	  --f-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
67	  --w-display:700; --ls-display:-0.035em; --em-style:normal;
68	  --radius:14px; --chart-radius:6px; --letterbox:#0c0c0d;
69	  --code-bg:#f5f5f7; --code-ink:#1d1d1f; --c-kw:#9b2393; --c-str:#c41a16; --c-num:#1c00cf; --c-com:#5d6c79; --c-fn:#0f68a0;
70	}
71	/* /THEME */
72	
73	/* THEME:keynote-black | Keynote Black | #2997ff | https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap */
74	html[data-theme="keynote-black"]{
75	  --bleed-bg:#2997ff; --bleed-ink:#000000;
76	  --bg:#000000; --bg2:#161618; --ink:#f5f5f7; --ink2:#a1a1a6;
77	  --rule:#38383a; --rule-strong:#f5f5f7; --brand:#2997ff; --brand-text:#2997ff; --on-brand:#000000;
78	  --hero-bg:#000000; --hero-ink:#f5f5f7; --hero-ink2:#a1a1a6; --hero-rule:#38383a; --hero-brand:#2997ff;
79	  --f-display:"Inter","SF Pro Display",-apple-system,"Helvetica Neue",Arial,sans-serif;
80	  --f-body:"Inter","SF Pro Text",-apple-system,"Helvetica Neue",Arial,sans-serif;
81	  --f-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
82	  --w-display:700; --ls-display:-0.035em; --em-style:normal;
83	  --em-fill:linear-gradient(90deg,#2997ff 0%,#c58bff 100%);
84	  --radius:14px; --chart-radius:6px; --letterbox:#000; --rec-mix:24%;
85	  --code-bg:#1c1c1e; --code-ink:#f5f5f7; --c-kw:#ff7ab2; --c-str:#ff8170; --c-num:#d9c97c; --c-com:#8e8e93; --c-fn:#6bdfff;
86	}
87	/* /THEME */
88	
89	/* THEME:boardroom | Boardroom | #0b2545 | https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,600;0,8..60,700;1,8..60,400;1,8..60,600&family=Source+Sans+3:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap */
90	html[data-theme="boardroom"]{
91	  --bleed-bg:#c19a3d; --bleed-ink:#0b2545;
92	  --bg:#ffffff; --bg2:#eef1f6; --ink:#0b2545; --ink2:#46576f;
93	  --rule:#c8d0dc; --rule-strong:#0b2545; --brand:#c19a3d; --brand-text:#7a5a0a; --on-brand:#0b2545;
94	  --hero-bg:#0b2545; --hero-ink:#ffffff; --hero-ink2:#bcc8da; --hero-rule:#34507a; --hero-brand:#e2b658;
95	  --f-display:"Source Serif 4",Georgia,"Times New Roman",serif;
96	  --f-body:"Source Sans 3","Segoe UI",Helvetica,Arial,sans-serif;
97	  --f-mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
98	  --w-display:600; --ls-display:-0.015em; --em-style:italic; --f-ar-d:"Noto Naskh Arabic","Amiri","Geeza Pro",serif; --w-display-ar:600;
99	  --radius:2px; --chart-radius:0px; --letterbox:#050e1c;
100	  --code-bg:#0b2545; --code-ink:#e8eef7; --c-kw:#e2b658; --c-str:#9fd3a8; --c-num:#f0a07a; --c-com:#9fb0c8; --c-fn:#8fc1ff;
101	}
102	[data-theme="boardroom"] .slide[data-layout="title"]::before,
103	[data-theme="boardroom"] .slide[data-layout="closing"]::before{content:"";position:absolute;inset-block:0;inset-inline-start:0;width:28px;background:var(--brand)}
104	[data-theme="boardroom"] .kp-foot{border-top:1px solid var(--rule);padding-top:14px}
105	[data-theme="boardroom"] .chart .bar.s1{stroke:var(--rule-strong);stroke-width:1.5} /* the gold fill alone is 2.6:1 on white */
106	[data-theme="boardroom"] .slide:not([data-tone="hero"]):not([data-layout="title"]):not([data-layout="section"]):not([data-layout="closing"]):not([data-layout="full-bleed"]) > h2{border-inline-start:8px solid var(--brand);padding-inline-start:28px}
107	/* /THEME */
108	
109	/* THEME:swiss | Swiss | #d7000f | https://fonts.googleapis.com/css2?family=Inter+Tight:wght@500;600;700;800&family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap */
110	html[data-theme="swiss"]{
111	  --bleed-bg:#d7000f; --bleed-ink:#ffffff;
112	  --bg:#ffffff; --bg2:#f0f0f0; --ink:#111111; --ink2:#555555;
113	  --rule:#cfcfcf; --rule-strong:#111111; --brand:#d7000f; --brand-text:#d7000f; --on-brand:#ffffff;
114	  --hero-bg:#d7000f; --hero-ink:#ffffff; --hero-ink2:#ffffff; --hero-rule:#ffffff; --hero-brand:#ffffff;
115	  --f-display:"Inter Tight","Helvetica Neue",Helvetica,Arial,sans-serif;
116	  --f-body:"Inter","Helvetica Neue",Helvetica,Arial,sans-serif;
117	  --f-mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
118	  --w-display:700; --ls-display:-0.03em; --em-style:normal;
119	  --radius:0px; --chart-radius:0px; --letterbox:#1a1a1a;
120	  --code-bg:#111111; --code-ink:#f2f2f2; --c-kw:#ff7b7b; --c-str:#9ad1a0; --c-num:#f2c14e; --c-com:#9a9a9a; --c-fn:#8ab4ff;
121	}
122	[data-theme="swiss"] .slide:not([data-layout="title"]):not([data-layout="section"]):not([data-layout="closing"]):not([data-layout="full-bleed"]):not([data-tone="hero"])::before{content:"";position:absolute;top:0;inset-inline-start:120px;width:96px;height:20px;background:var(--brand)}
123	[data-theme="swiss"] .kp-foot{border-top:2px solid var(--ink);padding-top:14px}
124	/* Swiss grid signature: the title hangs in columns 1-5, the body starts in column 6; numbers sit on a hard 2px rule; no radius anywhere */
125	[data-theme="swiss"] [data-layout="bullets"]{display:grid;grid-template-columns:repeat(12,1fr);column-gap:40px;grid-template-rows:1fr;align-content:stretch}
126	[data-theme="swiss"] [data-layout="bullets"]>h2{grid-column:1/6;grid-row:1;align-self:start;margin:0;padding-top:48px}
127	[data-theme="swiss"] [data-layout="bullets"]>ul{grid-column:6/-1;grid-row:1;align-self:center;border-top:2px solid var(--ink);padding-top:40px;margin:0;padding-block-end:0}
128	[data-theme="swiss"] [data-layout="stats"] .stat b{border-top:0}
129	[data-theme="swiss"] .chip,[data-theme="swiss"] pre.code{border-radius:0}
130	/* /THEME */
131	
132	/* THEME:editorial | Editorial | #8f2d17 | https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400&family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap */
133	html[data-theme="editorial"]{
134	  --bleed-bg:#8f2d17; --bleed-ink:#f4efe6;
135	  --bg:#f4efe6; --bg2:#ebe4d6; --ink:#1c1a17; --ink2:#5a5347;
136	  --rule:#cfc5b2; --rule-strong:#1c1a17; --brand:#8f2d17; --brand-text:#8f2d17; --on-brand:#f4efe6;
137	  --hero-bg:#1c1a17; --hero-ink:#f4efe6; --hero-ink2:#bfb5a2; --hero-rule:#4a443b; --hero-brand:#e49467;
138	  --f-display:"Newsreader","Iowan Old Style",Georgia,serif;
139	  --f-body:"Inter","Helvetica Neue",Arial,sans-serif;
140	  --f-mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
141	  --w-display:400; --ls-display:-0.02em; --em-style:italic; --f-ar-d:"Noto Naskh Arabic","Amiri","Geeza Pro",serif; --w-display-ar:500;
142	  --radius:0px; --chart-radius:0px; --letterbox:#0e0d0b;
143	  --code-bg:#ebe4d6; --code-ink:#1c1a17; --c-kw:#8f2d17; --c-str:#28603a; --c-num:#7a4e00; --c-com:#655d4e; --c-fn:#1f4e79;
144	}
145	[data-theme="editorial"] .slide:not(:is([data-layout="title"],[data-layout="section"],[data-layout="closing"],[data-layout="full-bleed"],[data-tone="hero"]))::before{content:"";position:absolute;top:48px;inset-inline:120px;height:7px;border-top:2px solid var(--ink);border-bottom:1px solid var(--ink)}
146	[data-theme="editorial"] .kp-foot{border-top:1px solid var(--rule);padding-top:14px}
147	/* /THEME */
148	
149	/* THEME:studio | Studio | #f0a93b | https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap */
150	html[data-theme="studio"]{
151	  --bleed-bg:#f0a93b; --bleed-ink:#0a2a2f;
152	  --bg:#0a2a2f; --bg2:#0f3a40; --ink:#efe8d8; --ink2:#a9c0bd;
153	  --rule:#2c5a5f; --rule-strong:#efe8d8; --brand:#f0a93b; --brand-text:#f0a93b; --on-brand:#0a2a2f;
154	  --hero-bg:#061c20; --hero-ink:#efe8d8; --hero-ink2:#a9c0bd; --hero-rule:#2c5a5f; --hero-brand:#f0a93b;
155	  --f-display:"Instrument Serif",Georgia,serif;
156	  --f-body:"DM Sans","Helvetica Neue",Arial,sans-serif;
157	  --f-mono:"Space Mono",ui-monospace,Menlo,monospace;
158	  --w-display:400; --ls-display:-0.01em; --em-style:italic; --f-ar-d:"Noto Naskh Arabic","Amiri","Geeza Pro",serif; --w-display-ar:500;
159	  --radius:4px; --chart-radius:2px; --letterbox:#030f11; --rec-mix:22%;
160	  --code-bg:#061c20; --code-ink:#efe8d8; --c-kw:#f0a93b; --c-str:#a8d8b0; --c-num:#f6987a; --c-com:#8fb0ab; --c-fn:#7fd0d8;
161	}
162	[data-theme="studio"] .label::before{content:"";display:inline-block;width:14px;height:14px;border-radius:50%;background:var(--brand);margin-inline-end:16px;vertical-align:-1px}
163	[data-theme="studio"] .kp-foot{border-top:1px solid var(--rule);padding-top:14px}
164	/* /THEME */
165	
166	/* LIBRARY:THEMES:START */
167	/* Library themes are added per deck from library/themes by tools/add-look.mjs */
168	/* LIBRARY:THEMES:END */
169	
170	/* =====================================================================
171	   FONT PAIRINGS (core: 9 distinct looks; more pairings live in library/fonts and are added per deck by tools/add-look.mjs into the LIBRARY block):
172	   marker comment "FONTS:name | Label | google-fonts-url", then
173	   html[data-fonts="name"]{ --f-display --f-body --f-mono --w-display --ls-display --em-style [--display-scale] }, then a closing comment "/FONTS".
174	   ORDER MATTERS: FONTS blocks sit AFTER all THEME blocks so a pairing overrides the theme's own type.
175	   An empty url means system fonts. "Theme default" (no data-fonts) uses the theme's own fonts and url.
176	   ===================================================================== */
177	/* FONTS:inter | Inter / Inter | https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap */
178	html[data-fonts="inter"]{--f-display:"Inter",system-ui,sans-serif;--f-body:"Inter",system-ui,sans-serif;--f-mono:"JetBrains Mono",ui-monospace,monospace;--w-display:700;--ls-display:-0.035em;--em-style:normal}
179	/* /FONTS */
180	/* FONTS:fraunces | Fraunces / Inter | https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,500;0,9..144,600;1,9..144,500&family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap */
181	html[data-fonts="fraunces"]{--f-display:"Fraunces",Georgia,serif;--f-body:"Inter",system-ui,sans-serif;--f-mono:"JetBrains Mono",ui-monospace,monospace;--w-display:600;--ls-display:-0.01em;--em-style:italic}
182	/* /FONTS */
183	/* FONTS:plex | IBM Plex Sans / Plex Mono | https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap */
184	html[data-fonts="plex"]{--f-display:"IBM Plex Sans",system-ui,sans-serif;--f-body:"IBM Plex Sans",system-ui,sans-serif;--f-mono:"IBM Plex Mono",ui-monospace,monospace;--w-display:600;--ls-display:-0.02em;--em-style:normal}
185	/* /FONTS */
186	/* FONTS:playfair | Playfair / Source Sans | https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,600&family=Source+Sans+3:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap */
187	html[data-fonts="playfair"]{--f-display:"Playfair Display",Georgia,serif;--f-body:"Source Sans 3",system-ui,sans-serif;--f-mono:"JetBrains Mono",ui-monospace,monospace;--w-display:700;--ls-display:-0.02em;--em-style:italic}
188	/* /FONTS */
189	/* FONTS:grotesk | Space Grotesk / Inter | https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700;800&family=Space+Mono:wght@400;700&display=swap */
190	html[data-fonts="grotesk"]{--f-display:"Space Grotesk",system-ui,sans-serif;--f-body:"Inter",system-ui,sans-serif;--f-mono:"Space Mono",ui-monospace,monospace;--w-display:700;--ls-display:-0.035em;--em-style:normal}
191	/* /FONTS */
192	/* FONTS:system | System fonts |  */
193	html[data-fonts="system"]{--f-display:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;--f-body:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;--f-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;--w-display:700;--ls-display:-0.03em;--em-style:normal}
194	/* /FONTS */
195	
196	/* FONTS:sora | Sora / Inter | https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap */
197	html[data-fonts="sora"]{--f-display:"Sora",system-ui,sans-serif;--f-body:"Inter",system-ui,sans-serif;--f-mono:"JetBrains Mono",ui-monospace,monospace;--w-display:700;--ls-display:-0.04em;--em-style:normal}
198	/* /FONTS */
199	/* FONTS:cormorant | Cormorant Garamond / Source Sans | https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Source+Sans+3:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap */
200	html[data-fonts="cormorant"]{--display-scale:1.15;--f-display:"Cormorant Garamond",Georgia,serif;--f-body:"Source Sans 3",system-ui,sans-serif;--f-mono:"JetBrains Mono",ui-monospace,monospace;--w-display:600;--ls-display:-0.01em;--em-style:italic}
201	/* /FONTS */
202	/* FONTS:spectral | Spectral / Public Sans | https://fonts.googleapis.com/css2?family=Spectral:ital,wght@0,400;0,600;1,400;1,600&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap */
203	html[data-fonts="spectral"]{--f-display:"Spectral",Georgia,serif;--f-body:"Public Sans",system-ui,sans-serif;--f-mono:"IBM Plex Mono",ui-monospace,monospace;--w-display:600;--ls-display:-0.015em;--em-style:italic}
204	/* /FONTS */
205	
206	/* LIBRARY:FONTS:START */
207	/* Library font pairings are added per deck from library/fonts by tools/add-look.mjs */
208	/* LIBRARY:FONTS:END */
209	
210	/* Arabic / RTL: engine-level, not a pairing (a clean Arabic face first) */
211	html[dir="rtl"],[dir="rtl"],:lang(ar){--f-display:var(--f-ar-d,"IBM Plex Sans Arabic","Geeza Pro","Segoe UI",Tahoma,sans-serif);--f-body:var(--f-ar-b,"IBM Plex Sans Arabic","Geeza Pro","Segoe UI",Tahoma,sans-serif);--ls-display:0;--em-style:normal}
212	
213	</style>
214	<style id="kp-engine">
215	/* =====================================================================
216	   ENGINE CSS
217	   1 stage  2 type  3 layouts  4 builds  5 chart/code/table  6 chrome
218	   7 overview/presenter  8 print.  All sizes are px on a 1920x1080 canvas.
219	   Grid: 12 columns, 40px gutters, margins 120px (sides) / 96px (top, bottom).
220	   --fit (set by the engine) shrinks a slide's type when content is long.
221	   ===================================================================== */
222	*,*::before,*::after{box-sizing:border-box}
223	html{background:var(--letterbox,#000)}
224	body{margin:0;height:100vh;overflow:hidden;background:var(--letterbox,#000)}
225	.deck{position:absolute;left:0;top:0;width:1920px;height:1080px;transform-origin:0 0;overflow:hidden;background:var(--bg);contain:layout paint}
226	html:not(.kp-ready) .deck{visibility:hidden}
