245	.slide h3{font-family:var(--f-body);font-weight:600;font-size:calc(var(--t-h3)*var(--fh));line-height:1.2;letter-spacing:-0.01em}
246	.slide p{text-wrap:pretty}
247	.slide em{font-style:var(--em-style);color:var(--brand-text)}
248	.slide :is(h1,h2) em{background:var(--em-fill,linear-gradient(var(--brand-text),var(--brand-text)));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent;padding-inline-end:.1em;margin-inline-end:-.06em}
