440	[data-layout="case"] .vital span{display:block;font:500 max(28px,calc(26px*var(--fit)))/1.3 var(--f-mono);color:var(--ink2)}
441	[data-layout="case"] .vital b{display:block;font-family:var(--f-display);font-weight:var(--w-display);font-size:calc(84px*var(--fit));line-height:1.08;letter-spacing:-0.03em;white-space:nowrap}
442	[data-layout="case"] .vital small{font-size:max(28px,calc(28px*var(--fit)));letter-spacing:0;font-weight:400;color:var(--ink2);margin-inline-start:.2em}
