445	[data-layout="case"] .course{grid-column:6/-1;grid-row:5;list-style:none;padding:0;margin-inline-start:7px;border-inline-start:2px solid var(--rule-strong);align-self:start}
446	[data-layout="case"] .course li{position:relative;display:grid;grid-template-columns:170px 1fr;gap:0 20px;padding:calc(16px*var(--fit)) 0 calc(16px*var(--fit)) 36px;font-size:calc(36px*var(--fit));line-height:1.3}
447	[data-layout="case"] .course li::before{content:"";position:absolute;inset-inline-start:-9px;top:calc(16px*var(--fit) + .4em);width:16px;height:16px;border-radius:50%;background:var(--brand)}
448	[data-layout="case"] .course time{font:500 max(28px,calc(26px*var(--fit)))/1.5 var(--f-mono);color:var(--brand-text)}
449	/* ask: the raise (amount, use of funds, terms); also budget asks and grant requests */
450	[data-layout="ask"]{display:grid;grid-template-columns:repeat(12,1fr);column-gap:40px;grid-template-rows:auto auto 1fr auto;align-content:start}
451	[data-layout="ask"]>:is(h2,.label){grid-column:1/-1}
