461	[data-layout="ask"] .terms dt{font:500 max(28px,calc(24px*var(--fit)))/1.3 var(--f-mono);color:var(--ink2)}
462	[data-layout="ask"] .terms dd{margin:6px 0 0;font-size:calc(38px*var(--fit));font-weight:600;line-height:1.2}
463	/* rows: labelled rows (issue / rule / application / conclusion; situation / complication / resolution; claim / evidence) */
