477	[data-layout="quiz"] .opts li{counter-increment:q;display:flex;align-items:center;gap:28px;border:max(var(--rule-w,1px),2px) solid var(--rule-strong);border-radius:var(--radius);padding:calc(40px*var(--fit)) 40px;font-size:calc(50px*var(--fit));line-height:1.22;transition:background-color .4s,color .4s,border-color .4s}
478	[data-layout="quiz"] .opts li::before{content:counter(q,upper-alpha);flex:none;width:84px;height:84px;display:grid;place-items:center;border-radius:50%;background:var(--bg2);color:var(--ink);font:700 42px/1 var(--f-display)}
479	[data-layout="quiz"] .opts li[data-correct]{background:var(--brand);border-color:var(--brand);color:var(--on-brand)}
480	[data-layout="quiz"] .opts li[data-correct]::before{background:var(--on-brand);color:var(--brand-text)}
481	.kp-live .kb[data-kb="reveal"]:not(.is-on) li[data-correct]{background:transparent;border-color:var(--rule-strong);color:var(--ink)}
482	.kp-live .kb[data-kb="reveal"]:not(.is-on) li[data-correct]::before{background:var(--bg2);color:var(--ink)}
483	[data-layout="quiz"] .lede{margin-block-start:36px;font-size:max(28px,calc(34px*var(--fit)))}
484	/* materials: a board of swatches, textures or photos with captions */
485	[data-layout="materials"] h2{margin-block-end:40px}
486	[data-layout="materials"] .board{flex:1;min-height:0;display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:36px;counter-reset:mat}
487	[data-layout="materials"] .mat{display:flex;flex-direction:column;gap:20px;min-width:0;counter-increment:mat}
488	[data-layout="materials"] .mat::before{content:"";flex:1;min-height:160px;background:var(--tx,linear-gradient(transparent,transparent)),var(--sw,var(--bg2));border-radius:var(--radius);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--ink) 16%,transparent)}
489	[data-layout="materials"] .mat:has(img)::before{display:none}
490	[data-layout="materials"] .mat img{flex:1;min-height:0;width:100%;object-fit:cover;display:block;border-radius:var(--radius)}
491	[data-layout="materials"] .mat figcaption b{display:block;font-size:max(28px,calc(32px*var(--fit)));font-weight:650;line-height:1.2}
492	[data-layout="materials"] .mat figcaption span{display:block;margin-top:4px;font:max(28px,calc(24px*var(--fit)))/1.3 var(--f-mono);color:var(--ink2)}
