533	.kp-live .chart .val,.kp-live .chart .dot{transition:opacity .5s ease calc(var(--i)*.09s + .4s)}
534	.kp-live .chart .ln-path{transition:stroke-dashoffset 1.3s cubic-bezier(.65,0,.35,1)}
