1	#!/usr/bin/env node
2	/* Keynote Pro checker.  Usage:
3	     node check.mjs deck.html [more.html ...] [--themes] [--shots out/] [--outline]
4	   Opens each deck at 1920x1080, shows every slide with all builds revealed and reports, per slide:
5	     layout   unknown data-layout (the list is read from template.html), no title, bullet lists over 6 items or 40 words
6	     media    missing image file or alt, bad data-chart type, malformed data-values / table numbers
7	     fit      content outside the safe area, text wider than its box, audience text under 28px, contrast under 4.5:1
8	     other    console errors; WARNINGS (do not fail): slides without speaker notes
9	   Exit code 1 on any error.  --themes repeats the run in every theme; --shots saves PNGs (toolbar hidden); --outline prints the outline.
10	   Needs Playwright; it is searched for automatically (see findPlaywright).  If it fails the error prints the env-var line to use. */
11	import path from 'node:path';
12	import fs from 'node:fs';
13	import {pathToFileURL} from 'node:url';
14	
15	const args = process.argv.slice(2);
16	const flag = n => args.includes(n);
17	const wantOutline = args.includes('--outline');
18	const shotsDir = args.includes('--shots') ? args[args.indexOf('--shots') + 1] : null;
19	const files = args.filter((a, i) => !a.startsWith('--') && args[i - 1] !== '--shots');
20	if (!files.length) { console.error('usage: node check.mjs deck.html [...] [--themes] [--shots dir]'); process.exit(2); }
21	
22	const HERE = path.dirname(new URL(import.meta.url).pathname);
23	const HOME = process.env.HOME || '';
24	const tryDirs = d => { try { return fs.readdirSync(d).map(n => path.join(d, n)); } catch { return []; } };
25	async function findPlaywright() {
26	  const cands = [];
27	  if (process.env.PLAYWRIGHT_MODULE) cands.push(process.env.PLAYWRIGHT_MODULE);
28	  // Never the current folder: the checker runs on decks from anywhere, and a deck's folder must not be able to supply code.
29	  for (const root of [HERE, path.join(HOME, '.kp-tools')]) for (const n of ['playwright', 'playwright-core']) cands.push(path.join(root, 'node_modules', n));
30	  try { const g = (await import('node:child_process')).execSync('npm root -g', {encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 4000}).trim(); for (const n of ['playwright', 'playwright-core']) cands.push(path.join(g, n)); } catch {}
31	  for (const d of tryDirs(path.join(HOME, '.npm/_npx'))) for (const n of ['playwright', 'playwright-core']) cands.push(path.join(d, 'node_modules', n));
32	  for (const f of [() => import('playwright'), () => import('playwright-core')]) { try { const m = await f(); return {mod: m, from: 'import'}; } catch {} }
