57	  catch (e2) { console.error('check.mjs: Playwright found but no browser could start (' + String(e2.message).split('\n')[0] + ').\n  install one:  npx playwright install chromium\n' + hint(pwFound.from === 'import' ? null : pwFound.from, chrome)); process.exit(2); }
