59	
60	/* layouts the template knows: every data-layout="x" in template.html (next to this file) */
61	let LAYOUTS = null;
62	const TEMPLATE = [path.join(HERE, 'template.html'), path.join(HERE, '..', 'assets', 'template.html')].find(f => fs.existsSync(f)) || '';
63	try { LAYOUTS = [...new Set([...fs.readFileSync(TEMPLATE, 'utf8').matchAll(/data-layout="([a-z0-9-]+)"/g)].map(m => m[1]))]; } catch {}
64	const MIN_PX = 28, MIN_SMALL = 20;   /* audience text 28px; kickers, sources, captions, chart and diagram labels 20px */
