66	/* ---- static authoring checks, run once per deck in the page ---- */
67	async function authoring(layouts) {
68	  const out = [], warn = [];
69	  const slides = window.kp.slides;
70	  const name = e => { let t = e.tagName.toLowerCase(); if (e.className && typeof e.className === 'string' && e.className.trim()) t += '.' + e.className.trim().split(/\s+/)[0]; return t; };
71	  const words = t => t.trim().split(/\s+/).filter(Boolean).length;
72	  const imgLoaded = src => new Promise(res => { const im = new Image(); const t = setTimeout(() => res(false), 4000); im.onload = () => { clearTimeout(t); res(true); }; im.onerror = () => { clearTimeout(t); res(false); }; im.src = src; });
