74	  for (let i = 0; i < slides.length; i++) {
75	    const s = slides[i], n = i + 1, lay = s.dataset.layout, add = (el, m, fix) => out.push({slide: n, m: el + ' ' + m, fix});
76	    if (!lay) add('section', 'has no data-layout', 'add data-layout="bullets" (or another layout from README section 2)');
77	    else if (layouts && !layouts.includes(lay)) add(`data-layout="${lay}"`, 'is not a known layout', 'use one of: ' + layouts.join(', '));
78	    const hasTitle = [...s.querySelectorAll('h1,h2,blockquote,.big')].some(e => !e.closest('.notes') && e.textContent.trim());
79	    if (!hasTitle) add('slide', 'has no title (h1/h2, blockquote or .big)', 'start the slide with <h2>its one claim</h2>');
80	    for (const l of s.querySelectorAll('ul:not([class]),ol:not([class])')) {
81	      if (l.closest('.notes')) continue;
82	      const items = [...l.children].filter(c => c.tagName === 'LI');
83	      if (items.length > 6) add(name(l), `has ${items.length} bullets (max 6)`, 'cut to 5 or split into two slides');
84	      items.forEach((li, k) => { const w = words(li.textContent); if (w > 40) add('li #' + (k + 1), `has ${w} words (max 40)`, 'say the number, not the paragraph; move detail to the notes'); });
