86	    for (const im of s.querySelectorAll('img')) {
87	      const shown = im.getAttribute('src') || '';
88	      if (!im.hasAttribute('alt')) add(`img "${shown.slice(-30)}"`, 'has no alt attribute', 'add alt="what it shows" (alt="" if purely decorative)');
89	      if (!im.complete || !im.naturalWidth) { await new Promise(r => setTimeout(r, 150)); }
90	      if (!(im.complete && im.naturalWidth > 0)) add(`img "${shown.slice(-30)}"`, 'file did not load', 'check the path (relative to the deck) or remove the image');
91	    }
92	    if (s.dataset.bg && !(await imgLoaded(s.dataset.bg))) add(`data-bg="${s.dataset.bg.slice(-30)}"`, 'file did not load', 'check the path (relative to the deck)');
93	    for (const f of s.querySelectorAll('figure.chart, [data-chart]')) {
94	      const t = f.dataset.chart || 'column', v = f.dataset.values, tb = f.querySelector('table');
95	      if (!['column', 'bar', 'line'].includes(t)) add(`data-chart="${t}"`, 'is not a chart type', 'use column, bar or line');
