103	    }
104	    if (![...s.querySelectorAll('.notes')].some(a => a.textContent.trim())) noNotes.push(n);
105	  }
106	  if (noNotes.length) warn.push({slide: noNotes.length > 8 ? noNotes.slice(0, 8).join(', ') + ` ... (${noNotes.length} total)` : noNotes.join(', '), m: 'no speaker notes', fix: 'add <aside class="notes"><p>what to say</p></aside>'});
107	  return {out, warn};
108	}
109	
110	/* ---- runs inside the page, once per slide ---- */
111	function inPage([i, [MIN_PX, MIN_SMALL]]) {
112	  const s = window.kp.slides[i], out = [];
113	  const px = c => { const k = document.createElement('canvas'); k.width = k.height = 1; const x = k.getContext('2d', {willReadFrequently: true}); x.clearRect(0, 0, 1, 1); x.fillStyle = '#000'; x.fillStyle = c; x.fillRect(0, 0, 1, 1); const d = x.getImageData(0, 0, 1, 1).data; return [d[0], d[1], d[2], d[3] / 255]; };
