116	  const name = e => { let t = e.tagName.toLowerCase(); if (e.className && typeof e.className === 'string') t += '.' + e.className.trim().split(/\s+/)[0]; const tx = (e.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 28); return tx ? `${t} "${tx}"` : t; };
117	  const vis = e => { const cs = getComputedStyle(e), r = e.getBoundingClientRect(); return cs.display !== 'none' && cs.visibility !== 'hidden' && r.width > 0 && r.height > 0; };
118	  const skip = e => e.closest('.kp-foot,.notes,.sr-only,[data-bleed],.bleed,.num,.kp-ink');
119	  const fit = +(s.style.getPropertyValue('--fit') || 1);
120	  const sev = (m, fix) => out.push({m, fix});
121	  const hasBleedImg = !!s.querySelector('.bleed');
122	  for (const e of s.querySelectorAll('*')) {
123	    if (skip(e) || !vis(e)) continue;
124	    const own = [...e.childNodes].some(n => n.nodeType === 3 && n.nodeValue.trim());
125	    const box = own || /^(IMG|SVG|FIGURE|PRE|TABLE|UL|OL)$/i.test(e.tagName) && !e.closest('svg');
126	    const r = e.getBoundingClientRect();
127	    if (box && !e.closest('svg') || (own && e.closest('svg'))) {
128	      if (r.left < -1 || r.top < -1 || r.right > 1921 || r.bottom > 1081) sev(`${name(e)} runs off the slide`, 'shorten the text or split the slide');
129	      else if (r.left < 119 || r.right > 1801 || r.top < 95 || r.bottom > 985) sev(`${name(e)} leaves the safe area (x ${Math.round(r.left)}-${Math.round(r.right)}, y ${Math.round(r.top)}-${Math.round(r.bottom)})${fit < 1 ? ` after auto-fit ${fit}` : ''}`, 'shorten the text, drop an item, or use data-fit="off" with a smaller layout');
