136	      const svgText = e.closest('svg'); const fg0 = svgText ? cs.fill : cs.color;
137	      let clipCols = null;
138	      if (cs.webkitTextFillColor === 'rgba(0, 0, 0, 0)' || (cs.color === 'rgba(0, 0, 0, 0)' && !svgText)) {
139	        if (cs.webkitBackgroundClip === 'text' || cs.backgroundClip === 'text') clipCols = (cs.backgroundImage.match(/rgba?\([^)]*\)/g) || []); else continue; }
140	      let f = clipCols && clipCols.length ? px(clipCols[0]) : px(fg0), bg = [255, 255, 255, 1], stack = [], skipC = false, op = 1;
141	      for (let a = e === null ? null : (clipCols ? e.parentElement : e); a && a !== document.documentElement; a = a.parentElement) {
142	        const c = getComputedStyle(a); op *= +c.opacity;
143	        if (c.backgroundImage !== 'none' && c.backgroundClip !== 'text' && !/gradient/.test(c.backgroundImage) ) { skipC = true; break; }
144	        if (/gradient/.test(c.backgroundImage) && c.webkitBackgroundClip !== 'text') { skipC = true; break; }
145	        const b = px(c.backgroundColor); if (b[3] > 0) { stack.push(b); if (b[3] >= 1) break; }
146	        if (a === s) break;
147	      }
148	      if (hasBleedImg && s.dataset.layout === 'full-bleed') skipC = true;
149	      if (skipC) continue;
150	      bg = stack.reduceRight((acc, b) => over(b, acc), [255, 255, 255, 1]);
151	      if (op < 1) f = [f[0], f[1], f[2], f[3] * op];
152	      const L2 = lum(bg); let ratio = 99; for (const col of (clipCols && clipCols.length ? clipCols : [fg0])) { let ff = px(col); if (op < 1) ff = [ff[0], ff[1], ff[2], ff[3] * op]; const L1 = lum(over(ff, bg)); ratio = Math.min(ratio, (Math.max(L1, L2) + .05) / (Math.min(L1, L2) + .05)); }
153	      if (ratio < 4.5) sev(`${name(e)} contrast ${ratio.toFixed(2)}:1 (need 4.5)`, 'use --ink/--ink2, or darken --brand-text for this theme');
154	    }
155	  }
156	  if (s.scrollHeight > 1081 || s.scrollWidth > 1921) sev(`slide content scrolls (${s.scrollWidth}x${s.scrollHeight})`, 'shorten the content');
157	  return out;
158	}
159	
160	function dedupe(list) { const seen = new Map(); for (const x of list.sort((a, b) => a.slide - b.slide)) { const k = x.slide + '|' + x.m.replace(/"[^"]*"/, ''); if (seen.has(k)) seen.get(k).n++; else seen.set(k, {...x, n: 1}); } return [...seen.values()].map(x => x.n > 1 ? {...x, m: x.m + ` (x${x.n})`} : x); }
161	let failed = 0, total = 0;
162	for (const file of files) {
163	  const abs = path.resolve(file);
164	  const themeList = flag('--themes') ? await (async () => { const pg = await browser.newPage(); await pg.goto(pathToFileURL(abs).href); await pg.waitForFunction(() => window.kp && window.kp.ready); const l = await pg.evaluate(() => window.kp.themes); await pg.close(); return l; })() : [null];
165	  let firstRun = true;
166	  for (const theme of themeList) {
167	    const t0 = Date.now(), page = await browser.newPage({viewport: {width: 1920, height: 1080}});
168	    const errs = []; page.on('pageerror', e => errs.push(String(e))); page.on('console', m => { if (m.type() === 'error' && !/fonts\.g|ERR_INTERNET|ERR_NAME|Failed to load resource/.test(m.text() + (m.location()?.url || ''))) errs.push(m.text()); });
169	    await page.goto(pathToFileURL(abs).href); await page.waitForFunction(() => window.kp && window.kp.ready, null, {timeout: 15000});
170	    if (theme) { await page.evaluate(t => window.kp.applyLook(t, document.documentElement.getAttribute('data-fonts'), false), theme); await page.evaluate(() => document.fonts.ready); await page.evaluate(() => { document.querySelectorAll('.chart').length; window.kp.refit(); }); }
171	    await page.evaluate(() => document.documentElement.classList.add('kp-idle')); const n = await page.evaluate(() => window.kp.count); const issues = [], warns = [];
172	    if (firstRun) { firstRun = false; const a = await page.evaluate(authoring, LAYOUTS); issues.push(...a.out); warns.push(...a.warn); if (!LAYOUTS) warns.push({slide: '-', m: 'template.html not found next to check.mjs, layout names not verified', fix: 'keep check.mjs beside template.html'}); }
173	    if (shotsDir) await page.addStyleTag({content: '.kp-ui,.kp-pen,.kp-set,.kp-toast,.kp-hint{display:none!important}'});
174	    if (wantOutline) { console.log(`outline of ${path.basename(file)}:`); (await page.evaluate(() => window.kp.outline())).forEach(r => console.log(`  ${r.level ? '   ' : ''}${String(r.n).padStart(2)}. ${r.title}  [${r.layout}${r.builds ? ', ' + r.builds + ' builds' : ''}${r.magic ? ', magic' : ''}${r.notes ? '' : ', NO NOTES'}]`)); }
175	    for (let i = 0; i < n; i++) {
176	      await page.evaluate(i => window.kp.showAll(i), i); await page.waitForTimeout(40);
177	      const r = await page.evaluate(inPage, [i, [MIN_PX, MIN_SMALL]]); r.forEach(x => issues.push({slide: i + 1, ...x}));
178	      if (shotsDir) { fs.mkdirSync(shotsDir, {recursive: true}); await page.screenshot({path: path.join(shotsDir, `${path.basename(file, '.html')}${theme ? '-' + theme : ''}-${String(i + 1).padStart(2, '0')}.png`)}); }
179	    }
180	    errs.forEach(e => issues.push({slide: 0, m: 'console error: ' + e.slice(0, 160), fix: 'fix the script error'}));
181	    total += n; failed += issues.length;
182	    console.log(`${issues.length ? 'FAIL' : 'ok  '} ${path.basename(file)}${theme ? ' [' + theme + ']' : ''}: ${n} slides, ${issues.length} issue${issues.length === 1 ? '' : 's'} (${((Date.now() - t0) / 1000).toFixed(1)}s)`);
183	    warns.forEach(w => console.log(`  warn  slide ${w.slide}: ${w.m}\n           fix: ${w.fix}`));
184	    dedupe(issues).slice(0, 40).forEach(x => console.log(`  slide ${x.slide || '-'}: ${x.m}\n           fix: ${x.fix}`));
185	    if (issues.length > 40) console.log(`  ... ${issues.length - 40} more`);
186	    await page.close();
187	  }
188	}
189	await browser.close();
190	process.exit(failed ? 1 : 0);
